                    "sql": "CREATE TABLE IF NOT EXISTS maplemonk.zouk_ga_sessions_consolidated ( date date, channel STRING, shop_name STRING, sessions int64); Create or replace table maplemonk.zouk_Sales_Cost_Source as with Sessions as ( select cast(date as date) date, \'SHOPIFY\' marketing_channel, \'SHOPIFY\' as marketplace, sum(cast(replace(sessions,\',\',\'\') as float64)) Sessions, sum(cast(replace(Visitors,\',\',\'\') as float64)) Visitors, sum(cast(replace(Add_To_Cart,\',\',\'\') as float64)) Add_To_Cart, sum(cast(replace(Checkout_Initiated,\',\',\'\') as float64)) Checkout_Initiated from MapleMonk.Zouk_Shopify_Funnel_Data group by 1,2,3 order by 1 desc ), returnsales as ( select cast(return_date as date) return_date ,marketing_channel ,case when lower(final_marketplace) like any (\'%amazon%\') then \'AMAZON\' when lower(final_marketplace) like any (\'%shopify%\') then \'SHOPIFY\' else upper(final_marketplace) end as marketplace ,sum(total_return_amount) TOTAL_RETURN_AMOUNT ,sum(total_return_amount_excl_tax) TOTAL_RETURN_AMOUNT_EXCL_TAX ,sum(total_returned_quantity) TOTAL_RETURNED_QUANTITY from maplemonk.zouk_RETURNS_CONSOLIDATED group by 1,2,3 order by 1 desc ), orders as ( select cast(FI.order_date as date) Date ,upper(final_marketplace) Marketplace ,upper(FI.CHANNEL) marketing_CHANNEL ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) Total_Sales ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) - ifnull(sum(case when (lower(ifnull(ORDER_STATUS,\'\')) like \'%cancel%\' or lower(ifnull(FINAL_SHIPPING_STATUS,\'\')) like \'%cancel%\') then ifnull(FI.SELLING_PRICE,0) else 0 end),0) TOTAL_SALES_EXCL_CANCL ,count(distinct FI.order_id) Total_Orders ,count(distinct FI.order_id) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.order_id end) Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) as New_Customer_Orders ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) 