 Brand_Spend ,sum(ifnull(impressions,0)) as ad_impressions ,sum(ifnull(clicks,0)) as ad_clicks ,sum(ifnull(conversions,0)) as ad_conversions ,sum(ifnull(conversion_value,0)) as ad_sales ,sum(ifnull(link_clicks,0)) as ad_link_clicks ,sum(ifnull(reach,0)) as ad_reach ,sum(ifnull(frequency,0)) as ad_frequency from maplemonk.zouk_MARKETING_CONSOLIDATED group by 1,2,3 ), Final_Spends as ( select COALESCE(ss.date,sdc.date) as Date ,COALESCE(ss.final_marketplace,sdc.marketplace) as Marketplace ,COALESCE(ss.mapped_marketplace,sdc.marketplace) as Mapeed_marketplace ,upper(marketing_Channel) marketing_Channel ,(ifnull(ss.share,1) * spend )AS spend ,(ifnull(ss.share,1) * Brand_Spend )AS Brand_Spend ,(ifnull(ss.share,1) * ad_impressions )AS ad_impressions ,(ifnull(ss.share,1) * ad_clicks )AS ad_clicks ,(ifnull(ss.share,1) * ad_conversions )AS ad_conversions ,(ifnull(ss.share,1) * ad_sales )AS ad_sales ,(ifnull(ss.share,1) * ad_link_clicks )AS ad_link_clicks ,(ifnull(ss.share,1) * ad_reach )AS ad_reach ,(ifnull(ss.share,1) * ad_frequency )AS ad_frequency from Sales_Share ss Full Outer join spendd2c sdc on cast(ss.date as date) = cast(sdc.date as date) and lower(ss.mapped_marketplace) = lower(sdc.marketplace) ) select coalesce(fi.Date,MC.date, SC.date) as date, upper(coalesce(fi.marketplace,MC.marketplace,RS.marketplace, SC.marketplace)) as Marketplace, upper(coalesce(fi.marketing_channel,MC.marketing_Channel,RS.marketing_channel, SC.marketing_channel)) as Marketing_Channel, Total_Sales, TOTAL_SALES_EXCL_CANCL, SC.sessions, Total_Orders, Orders_EXCL_CANCL, New_Customer_Orders, New_Customer_Orders_EXCL_CANCL, Total_New_Customers, New_Customers_EXCL_CANCL, TOTAL_Unique_Customers, Unique_Customers_EXCL_CANCL, Repeat_Customers, Repeat_Customers_EXCL_CANCL, TOTAL_DISCOUNT, TOTAL_DISCOUNT_EXCL_CANCL, TOTAL_TAX, TAX_EXCL_CANCL, TOTAL_SHIPPING_PRICE, SHIPPING_PRICE_EXCL_CANCL, New_Customer_DISCOUNT, New_Customer_Discount_EXCL_CANCL, TOTAL_QUANTITY, QUANTITY_EXCL_CANCL, RS.TOTAL_RETURNED_QUANTITY as Return_Quantity, RS.TOTAL_RETURN_AMOUNT as Return_Value, Cancelled_Orders, Net_Orders, Delivered_Orders, Delivered_Revenue, Dispatched_Orders, Dispatched_Revenue, Realised_Orders, Realised_Revenue, spend as marketing_spend, Brand_Spend, COD_Orders, Repeat_Customer_Revenue, MC.ad_conversions, MC.ad_impressions, MC.ad_clicks, MC.ad_sales, Checkout_Initiated, Add_To_Cart, Visitors, ad_frequency, ad_reach, MC.ad_link_clicks from orders FI full outer join Final_Spends MC on FI.Date = MC.date and lower(FI.marketing_channel)=lower(MC.marketing_channel) and lower(FI.Marketplace)=lower(MC.Marketplace) full outer join returnsales RS on RS.return_date = coalesce(FI.date, MC.date) and lower(RS.marketing_Channel) = lower(coalesce(FI.marketing_Channel,MC.marketing_channel)) and lower(RS.marketplace)=lower(coalesce(FI.marketplace,MC.marketplace)) full outer join SESSIONS SC on coalesce(FI.Date,MC.date,RS.return_date)=SC.Date and lower(coalesce(FI.Marketing_Channel,MC.marketing_channel,RS.marketing_Channel))=lower(SC.Marketing_Channel) and lower(coalesce(FI.marketplace,MC.marketplace,RS.marketplace))=lower(SC.Marketplace);",
